export function shape(v: any): number[] {
  return Array.isArray(v) ? [v.length, ...shape(v[0])] : [];
}
export function at(v: any, index: number[]) {
  return index.reduce((a, i) => a?.[i], v);
}
export function numeric(v: any): number[] {
  return Array.isArray(v)
