  return x.flatMap((xx, i) => y.flatMap((yy, j) => [xx, yy, z[i][j]]));
}
export function projectedUpdate(event: Doc, paths: string[], indices: number[][]) {
  const delta = paths.map((p, i) => at(event.parameters?.[p.split('/')[1]]?.delta, indices[i]) ?? 0);
